/// <summary>
/// Find by reference
/// </summary>
/// <param name = "_custInvoiceJourRecID">CustInvoiceJourRecID</param>
/// <param name = "_forUpdate">_forUpdate</param>
/// <returns>METCustInvoiceJour</returns>
static public METCustInvoiceJour find(RefRecId _custInvoiceJourRecID, boolean _forUpdate = false)
{
    METCustInvoiceJour metCustInvoiceJour;
    if(_custInvoiceJourRecID)
    {
        metCustInvoiceJour.selectForUpdate(_forUpdate);
        select firstonly metCustInvoiceJour
           where   metCustInvoiceJour.CustInvoiceJour  == _custInvoiceJourRecID;
    }
    return metCustInvoiceJour;
}

/// <summary>
/// Find or create by cust invoice jour reference
/// </summary>
/// <param name = "_custInvoiceJourRecID">_salesLineRecID</param>
/// <param name = "_forUpdate">_forUpdate</param>
/// <returns>Found/created record</returns>
static public METCustInvoiceJour findOrCreate(RefRecId _custInvoiceJourRecID, boolean _forUpdate = false)
{
    if(!_custInvoiceJourRecID)
    {
        return null;
    }
    METCustInvoiceJour metCustInvoiceJour = METCustInvoiceJour::find(_custInvoiceJourRecID, _forUpdate);
    if(!metCustInvoiceJour)
    {
        metCustInvoiceJour.initValue();
        metCustInvoiceJour.CustInvoiceJour = _custInvoiceJourRecID;
        metCustInvoiceJour.insert();
    }
    return metCustInvoiceJour;
}

/// <summary>
/// initValue
/// </summary>
public void initValue()
{
    super();
    this.IntegrationStatus   = METIntegrationStatus::None;
}

    /// <summary>
    /// Update Integration status
    /// </summary>
    /// <param name = "_integrationStatus">Integration Status</param>
    public void updateIntegrationStatus(METIntegrationStatus _integrationStatus)
    {
        
        ttsbegin;

        this.selectForUpdate(true);
        this.IntegrationStatus = _integrationStatus;
        this.update();

        ttscommit;
    }
